  - level: 8
    grants: ["Roll on the Phobia Table again", "+1 to save vs insanity"]
  - level: 10
    grants: ["Roll on the Neurosis Table", "+1 to save vs insanity"]
  - level: 12
    grants: ["Roll on the Psychosis Table"]
  - level: 14
